const updateStatus = `-- name: UpdateStatus :execrows
UPDATE applications
SET status = $1,
    updated_at = $2,
    due_at = CASE WHEN $3::boolean THEN NULL ELSE due_at END
WHERE id = $4 AND status = $5
`

type UpdateStatusParams struct {
	NewStatus string
	Now       time.Time
	Terminal  bool
	ID        uuid.UUID
	OldStatus string
}

// Смена статуса только из ожидаемого: параллельная смена даст 0 строк → 409.
// У конечных статусов срок готовности сбрасывается (Б5).
func (q *Queries) UpdateStatus(ctx context.Context, arg UpdateStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateStatus,
		arg.NewStatus,
		arg.Now,
		arg.Terminal,
		arg.ID,
		arg.OldStatus,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
